public static Stack<Integer> splitEven(Stack<Integer> s) {
    Stack<Integer> odd = new Stack<Integer>();
    Stack<Integer> even = new Stack<Integer>();
    while (!s.isEmpty()) {
        int x = s.pop();
        if (x % 2 == 0) {
            even.push(x);
        } else {
            odd.push(x);
        }
    }
    Stack<Integer> result = new Stack<Integer>();
    while (!even.isEmpty()) {
        result.push(even.pop());
    }
    while (!odd.isEmpty()) {
        s.push(odd.pop());
    }
    return result;
}

public static boolean isSorted(Stack<Integer> s) {
    Stack<Integer> temp = new Stack<Integer>();
    boolean sorted = true;
    while (!s.isEmpty()) {
        int x = s.pop();
        if (!s.isEmpty() && x > s.top()) {
            sorted = false;
        }
        temp.push(x);
    }
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return sorted;
}

